def circle_overlaps_rectangle(radius, x_center, y_center, x1, y1, x2, y2):
 closest_x=max(x1,min(x_center,x2));closest_y=max(y1,min(y_center,y2))
 return (x_center-closest_x)**2+(y_center-closest_y)**2<=radius**2

